export type Notebook = { id: string; name: string }

export type Note = {
  id: string
  notebook: string
  title: string
  body: string
  updated: string
  reads: number
}

export const ALL = "all"

export const FEATURED = "owning-books"

export const NOTEBOOKS: Notebook[] = [
  { id: ALL, name: "Everything" },
  { id: "recipes", name: "Recipes" },
  { id: "garden", name: "Garden" },
  { id: "reading", name: "Reading" },
  { id: "trips", name: "Trips" },
  { id: "scraps", name: "Scraps" },
]

export const NOTES: Note[] = [
  {
    id: "owning-books",
    notebook: "reading",
    title: "On owning books",
    body: `Most of what I remember from a book is in the ((margins)): an arrow, a question mark, a small argument with a dead author.

The good bits get ==a swipe of yellow== so I can find them on the next read, and the parts I do not believe get __a red pencil__.

By the third reading the book is more mine than the ~~writer's~~, which is the whole point of owning one.`,
    updated: "10 minutes ago",
    reads: 7,
  },
  {
    id: "porridge",
    notebook: "recipes",
    title: "Porridge, the slow way",
    body: `Oats, water, a pinch of salt. Nothing else until the end.

Bring the water to a ==small boil==, then turn it down until it just shivers. Stir with the wooden spoon, ((always the same direction)). My gran was firm about it.

Twelve minutes. Honey, a splash of cold milk, and __eat it standing at the window__.`,
    updated: "2 hours ago",
    reads: 7,
  },
  {
    id: "soup",
    notebook: "recipes",
    title: "Soup that forgives",
    body: `Any sad vegetables, one onion, plenty of butter.

Cook the onion until it gives up, ==then add everything else==. Water to cover. Salt, a bay leaf, patience.

~~Cream~~ Not needed. A spoon of yoghurt and black pepper on top.`,
    updated: "Yesterday",
    reads: 3,
  },
  {
    id: "toast",
    notebook: "recipes",
    title: "Toast, honestly",
    body: `Good bread, ((thick)) slices, a toaster you trust.

Butter goes on while it is __still too hot to hold__. Jam only if you mean it.`,
    updated: "Last week",
    reads: 12,
  },
  {
    id: "beds",
    notebook: "garden",
    title: "What went in this week",
    body: `Sunday: sweet peas along the fence, ==nine of them==, in the wet corner.
Monday: rain. Nothing.
Wednesday: the first radishes are up. ((Already.))

Still to do: move the rosemary before it sulks.`,
    updated: "Tuesday",
    reads: 4,
  },
  {
    id: "slugs",
    notebook: "garden",
    title: "Slugs: a truce",
    body: `They get the outer lettuce. I get the inner ones. __Everyone eats.__

~~Beer traps~~ Did not work, and smelled.`,
    updated: "Last month",
    reads: 2,
  },
  {
    id: "lisbon",
    notebook: "trips",
    title: "Lisbon, three days",
    body: `Day one: tram 28 before the crowds, then ==pastel de nata==. Two, not one.
Day two: walk uphill on purpose. ((Bring the good shoes.))
Day three: a bookshop with a cat, and __no plan at all__.

Ask Jo about the tiles.`,
    updated: "3 days ago",
    reads: 5,
  },
  {
    id: "scrap-1",
    notebook: "scraps",
    title: "Things to ask the printer",
    body: `Is the blue ==actually== that blue?
Deckle edge: extra, or included?
Proofs by Thursday, ((please)).`,
    updated: "Monday",
    reads: 1,
  },
]

export type MarkKind = "highlight" | "underline" | "circle" | "strike"

export const MARKS: Record<MarkKind, { open: string; close: string; label: string }> = {
  highlight: { open: "==", close: "==", label: "Highlight" },
  underline: { open: "__", close: "__", label: "Underline" },
  circle: { open: "((", close: "))", label: "Circle" },
  strike: { open: "~~", close: "~~", label: "Cross out" },
}

export type Piece = { text: string; mark?: MarkKind }

const MARK_RE = /==(.+?)==|__(.+?)__|\(\((.+?)\)\)|~~(.+?)~~/g
const ORDER: MarkKind[] = ["highlight", "underline", "circle", "strike"]

export function parseLine(line: string): Piece[] {
  const out: Piece[] = []
  let at = 0
  for (const m of line.matchAll(MARK_RE)) {
    const i = m.index ?? 0
    if (i > at) out.push({ text: line.slice(at, i) })
    const k = m.findIndex((g, n) => n > 0 && g !== undefined) - 1
    out.push({ text: m[k + 1] ?? "", mark: ORDER[k] })
    at = i + m[0].length
  }
  if (at < line.length) out.push({ text: line.slice(at) })
  return out
}

export function stripMarks(body: string): string {
  return body
    .split("\n")
    .map((l) =>
      parseLine(l)
        .map((p) => p.text)
        .join("")
    )
    .join("\n")
}

export const wordCount = (body: string): number => stripMarks(body).split(/\s+/).filter(Boolean).length

export type Selection = { text: string; start: number; end: number }

export function toggleMark(text: string, start: number, end: number, kind: MarkKind): Selection | null {
  const { open, close } = MARKS[kind]
  if (end <= start) return null
  const selected = text.slice(start, end)
  if (text.slice(start - open.length, start) === open && text.slice(end, end + close.length) === close) {
    const next = text.slice(0, start - open.length) + selected + text.slice(end + close.length)
    return { text: next, start: start - open.length, end: end - open.length }
  }
  if (selected.length > open.length + close.length && selected.startsWith(open) && selected.endsWith(close)) {
    const inner = selected.slice(open.length, selected.length - close.length)
    return { text: text.slice(0, start) + inner + text.slice(end), start, end: start + inner.length }
  }
  const parts: { from: number; to: number }[] = []
  let cursor = start
  for (const line of selected.split("\n")) {
    const lead = line.length - line.trimStart().length
    const body = line.trim()
    if (body) parts.push({ from: cursor + lead, to: cursor + lead + body.length })
    cursor += line.length + 1
  }
  if (!parts.length) return null
  let next = text
  for (const p of [...parts].reverse()) next = next.slice(0, p.from) + open + next.slice(p.from, p.to) + close + next.slice(p.to)
  const added = parts.length * (open.length + close.length)
  return { text: next, start: parts[0].from + open.length, end: parts[parts.length - 1].to + added - close.length }
}

import * as React from "react"

import { Annotate, type AnnotateType } from "@/components/ui/annotate"
import { parseLine, type MarkKind } from "@/components/blocks/notes-app/components/notes-app-data"

export const MARK_LOOK: Record<MarkKind, { type: AnnotateType; color: "yellow" | "blue" | "red"; kind?: "wavy" }> = {
  highlight: { type: "highlight", color: "yellow" },
  underline: { type: "underline", color: "blue", kind: "wavy" },
  circle: { type: "circle", color: "red" },
  strike: { type: "strike-through", color: "red" },
}

export function NotesAppMarked({ body, seed }: { body: string; seed: string }) {
  return (
    <div className="text-[17px] leading-7 wrap-break-word">
      {body.split("\n").map((line, i) => (
        <div key={i} className="min-h-7">
          {parseLine(line).map((piece, j) => {
            if (!piece.mark) return <React.Fragment key={j}>{piece.text}</React.Fragment>
            const look = MARK_LOOK[piece.mark]
            return (
              <Annotate key={j} type={look.type} color={look.color} kind={look.kind} seed={`${seed}:${i}:${j}`}>
                {piece.text}
              </Annotate>
            )
          })}
        </div>
      ))}
    </div>
  )
}

"use client"

import * as React from "react"

import { Empty, EmptyDescription, EmptyHeader, EmptyMedia, EmptyTitle } from "@/components/ui/empty"
import { Paper } from "@/components/ui/paper"
import { ALL, FEATURED, NOTEBOOKS, NOTES, type Note } from "@/components/blocks/notes-app/components/notes-app-data"
import { NotesAppEditor, type EditorMode } from "@/components/blocks/notes-app/components/notes-app-editor"
import { NotesAppNoteList } from "@/components/blocks/notes-app/components/notes-app-note-list"
import { cn } from "@/lib/utils"

type Props = {
  className?: string
  defaultNotes?: Note[]
  onNotesChange?: (notes: Note[]) => void
}

export default function NotesApp({ className, defaultNotes = NOTES, onNotesChange }: Props) {
  const [notes, setNotes] = React.useState<Note[]>(defaultNotes)
  const commit = (next: Note[]) => {
    setNotes(next)
    onNotesChange?.(next)
  }
  const [notebook, setNotebook] = React.useState(ALL)
  const [selectedId, setSelectedId] = React.useState<string | null>(defaultNotes.some((n) => n.id === FEATURED) ? FEATURED : (defaultNotes[0]?.id ?? null))
  const [mode, setMode] = React.useState<EditorMode>("page")
  const [view, setView] = React.useState<"list" | "editor">("list")
  const counter = React.useRef(0)
  const shelf = React.useRef<HTMLHeadingElement>(null)
  const [handBack, setHandBack] = React.useState(false)

  const note = notes.find((n) => n.id === selectedId)
  const notebookName = NOTEBOOKS.find((nb) => nb.id === note?.notebook)?.name ?? ""

  React.useEffect(() => {
    if (!handBack) return
    shelf.current?.focus()
    setHandBack(false)
  }, [handBack])

  const grid = React.useRef<HTMLDivElement>(null)
  const shown = React.useRef(view)
  React.useEffect(() => {
    if (shown.current === view) return
    shown.current = view
    if (handBack) return
    const gone = grid.current?.querySelector<HTMLElement>(view === "editor" ? "[data-slot=notes-app-list]" : "[data-slot=notes-app-editor]")
    if (!gone || getComputedStyle(gone).display !== "none") return
    const target = view === "editor" ? grid.current?.querySelector<HTMLElement>("[data-slot=notes-app-editor]") : (grid.current?.querySelector<HTMLElement>("[data-slot=notes-app-list] [aria-current=true]") ?? shelf.current)
    target?.focus()
  }, [view, handBack])

  const open = (id: string) => {
    setSelectedId(id)
    setMode("page")
    setView("editor")
  }

  const create = () => {
    const id = `page-${counter.current++}`
    const home = notebook === ALL ? "scraps" : notebook
    commit([{ id, notebook: home, title: "", body: "", updated: "just now", reads: 0 }, ...notes])
    setSelectedId(id)
    setMode("write")
    setView("editor")
  }

  const change = (patch: Partial<Pick<Note, "title" | "body" | "reads">>) =>
    commit(notes.map((n) => (n.id === selectedId ? { ...n, ...patch, updated: "just now" } : n)))

  const remove = () => {
    const rest = notes.filter((n) => n.id !== selectedId)
    commit(rest)
    setSelectedId(rest.find((n) => notebook === ALL || n.notebook === notebook)?.id ?? null)
    setMode("page")
    setView("list")
    setHandBack(true)
  }

  return (
    <div className="@container/notes w-full">
      <div
        ref={grid}
        data-slot="notes-app"
        data-view={view}
        className={cn(
          "group/notes grid h-[48rem] max-h-[100svh] min-h-[32rem] w-full grid-cols-1 grid-rows-[minmax(0,1fr)] gap-6 p-4 pt-10 @4xl/notes:grid-cols-[minmax(20rem,24rem)_minmax(0,1fr)] @4xl/notes:p-6 @4xl/notes:pt-12",
          className
        )}
      >
        <NotesAppNoteList
          notes={notes}
          notebook={notebook}
          onNotebookChange={setNotebook}
          selectedId={selectedId}
          onSelect={open}
          onNew={create}
          headingRef={shelf}
          className="group-data-[view=editor]/notes:@max-4xl/notes:hidden"
        />
        {note ? (
          <NotesAppEditor
            key={note.id}
            note={note}
            notebookName={notebookName}
            mode={mode}
            onModeChange={setMode}
            onChange={change}
            onDelete={remove}
            onBack={() => setView("list")}
            className="group-data-[view=list]/notes:@max-4xl/notes:hidden"
          />
        ) : (
          <Paper as="section" stock="card" aria-label="Editor" className="grid place-items-center group-data-[view=list]/notes:@max-4xl/notes:hidden">
            <Empty seed="no-page">
              <EmptyHeader>
                <EmptyMedia pose="idle" size={104} />
                <EmptyTitle>Pick a page</EmptyTitle>
                <EmptyDescription>Open one from the shelf, or start a new page with the button up there.</EmptyDescription>
              </EmptyHeader>
            </Empty>
          </Paper>
        )}
      </div>
    </div>
  )
}
